INSERT IGNORE INTO `subcategories` (`category_id`, `name`, `name_en`, `slug`) SELECT c.`id`, 'Продажі', 'Sales', 'sales' FROM `categories` c WHERE c.`slug` = 'business-marketing' LIMIT 1;

