-- Clay — Продажі
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'clay.com' OR LOWER(`name`) = LOWER('Clay'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Clay', NULL, 'https://www.clay.com', NULL, NULL, 'Платформа для продажів і маркетингу, що збагачує дані про клієнтів із 150+ джерел і досліджує компанії за допомогою AI-агентів Claygent.', 'A sales and marketing platform that enriches prospect data from 150+ providers and researches companies with Claygent AI agents.', 'Clay допомагає командам продажів і маркетингу знаходити потенційних клієнтів, збагачувати дані про них і запускати кампанії. У таблицях Clay дані послідовно запитуються в понад 150 постачальників (каскадний пошук email і телефонів), а AI-агенти Claygent самостійно досліджують сайти компаній і знаходять потрібні факти. Далі можна відстежувати сигнали (зміну роботи, наміри на сайті), синхронізувати дані з CRM і запускати email-кампанії. Тарифи: Free — 100 кредитів даних і 500 дій на місяць; Launch — $185 на місяць (2 500 кредитів); Growth — $495 на місяць (6 000 кредитів, синхронізація з CRM, API); Enterprise — за запитом; річна оплата дешевша на 10%.', 'Clay helps sales and marketing teams find prospects, enrich their data and launch campaigns. In Clay tables, data is requested from more than 150 providers in sequence (waterfall email and phone lookup), and Claygent AI agents research company websites on their own to find the facts you need. You can then track signals (job changes, website intent), sync data to your CRM and launch email campaigns. Plans: Free — 100 data credits and 500 actions a month; Launch — $185 a month (2,500 credits); Growth — $495 a month (6,000 credits, CRM sync, API); Enterprise on request; annual billing is 10% cheaper.', 'Збагачення даних із 150+ постачальників
AI-агенти Claygent для дослідження компаній
Сигнали: зміна роботи, наміри на сайті
Синхронізація з CRM та email-кампанії', 'Data enrichment from 150+ providers
Claygent AI agents for company research
Signals: job changes, website intent
CRM sync and email campaigns', 'Команди продажів, growth-маркетологи та RevOps, які будують outbound на даних.', 'Sales teams, growth marketers and RevOps building data-driven outbound.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
