SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'lemlist.com' OR LOWER(`name`) = LOWER('lemlist'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'lemlist', NULL, 'https://www.lemlist.com', NULL, NULL, 'Платформа холодних розсилок і мультиканального outreach: база 650+ млн лідів, AI-персоналізація та послідовності в email, LinkedIn, дзвінках, SMS і WhatsApp.', 'A cold email and multichannel outreach platform: a 650M+ lead database, AI personalisation and sequences across email, LinkedIn, calls, SMS and WhatsApp.', 'lemlist поєднує пошук лідів, автоматизацію outreach і AI-персоналізацію в одному інструменті. У базі понад 650 млн контактів можна знайти людей із потрібними ознаками, а потім звертатися до них автоматичними послідовностями через email, LinkedIn, дзвінки, SMS і WhatsApp. AI-агент lemAgent допомагає складати кампанії й персоналізувати повідомлення, а прогрів пошти й інструменти доставлюваності підтримують листи поза спамом. Тарифи: Email — $69 на місяць ($55 при річній оплаті, 50 000 листів); Multichannel — $109 на місяць ($87 при річній оплаті, усі канали); Enterprise — за запитом.', 'lemlist combines lead search, outreach automation and AI personalisation in one tool. In a database of 650M+ contacts you can find people who match your criteria and then reach them with automated sequences over email, LinkedIn, calls, SMS and WhatsApp. The lemAgent AI agent helps build campaigns and personalise messages, while email warm-up and deliverability tools keep emails out of spam. Plans: Email — $69 a month ($55 billed annually, 50,000 emails); Multichannel — $109 a month ($87 billed annually, all channels); Enterprise on request.', 'База 650+ млн лідів
Послідовності в email, LinkedIn, дзвінках, SMS, WhatsApp
AI-агент lemAgent і персоналізація
Прогрів пошти та доставлюваність', '650M+ lead database
Sequences across email, LinkedIn, calls, SMS, WhatsApp
lemAgent AI agent and personalisation
Email warm-up and deliverability', 'Продавці, SDR, агенції та засновники, які шукають клієнтів через холодний outreach.', 'Salespeople, SDRs, agencies and founders who find customers through cold outreach.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
