SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gong.io' OR LOWER(`name`) = LOWER('Gong'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Gong', NULL, 'https://www.gong.io', NULL, NULL, 'Платформа revenue intelligence: записує й аналізує дзвінки та листи з клієнтами, прогнозує угоди й дає AI-агентів для команд продажів.', 'A revenue intelligence platform: it records and analyses customer calls and emails, forecasts deals and provides AI agents for sales teams.', 'Gong — «операційна система» для команд продажів на основі AI. Він автоматично записує дзвінки та зустрічі з клієнтами, транскрибує й аналізує їх, а також враховує листування, щоб показати, що відбувається в кожній угоді: ризики, наступні кроки, згадки конкурентів. На цих даних працюють прогнозування виручки, коучинг продавців, автоматизація outreach і AI-агенти, що виконують рутинні задачі. Gong інтегрується з CRM та іншими інструментами без доплати. Ціни не опубліковано: ліцензії рахуються за користувача плюс платформний збір залежно від розміру команди; пропозицію готують індивідуально.', 'Gong is an AI-powered ''operating system'' for revenue teams. It automatically records customer calls and meetings, transcribes and analyses them, and takes email into account to show what is happening in every deal: risks, next steps and competitor mentions. On top of this data it provides revenue forecasting, rep coaching, outreach automation and AI agents that handle routine tasks. Gong integrates with your CRM and other tools at no extra cost. Pricing is not published: licences are per user plus a platform fee based on team size, and proposals are tailored.', 'Запис і AI-аналіз дзвінків та зустрічей
Аналіз угод: ризики й наступні кроки
Прогнозування виручки
Коучинг продавців і AI-агенти', 'Call and meeting recording with AI analysis
Deal insights: risks and next steps
Revenue forecasting
Rep coaching and AI agents', 'Відділи продажів і керівники B2B-компаній середнього та великого розміру.', 'Sales teams and revenue leaders at mid-sized and large B2B companies.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
