INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Outreach', NULL, 'https://www.outreach.ai', NULL, NULL, 'AI-платформа для команд продажів: агенти для менеджерів, керівників і RevOps допомагають будувати воронку, закривати угоди й прогнозувати виручку.', 'An AI platform for revenue teams: agents for account executives, sales leaders and RevOps help build pipeline, close deals and forecast revenue.', 'Outreach позиціонує себе як платформу AI-агентів для команд продажів. Агенти, налаштовані під різні ролі, допомагають знаходити й опрацьовувати потенційних клієнтів, вести послідовності контактів, готуватися до зустрічей, оцінювати стан угод і складати прогнози. Платформа охоплює sales engagement, аналіз розмов, управління угодами та прогнозування. Модель оплати змішана: місця за користувачів (без платформного збору) плюс AI-кредити за використання; пакети Amplify Essentials, Core, Plus і Pro містять від 10 000 до 100 000 AI-кредитів. Конкретні ціни не опубліковано — пропозицію готують під команду.', 'Outreach presents itself as an AI agent platform for revenue teams. Agents tailored to different roles help find and work prospects, run contact sequences, prepare for meetings, assess deal health and build forecasts. The platform covers sales engagement, conversation intelligence, deal management and forecasting. Pricing is hybrid: per-user seats (no platform fee) plus AI credits for usage; the Amplify Essentials, Core, Plus and Pro packages include 10,000 to 100,000 AI credits. Exact prices are not published — proposals are tailored to the team.', 'AI-агенти під ролі в команді продажів
Послідовності контактів і sales engagement
Аналіз розмов і стану угод
Прогнозування виручки', 'Role-specific AI agents for revenue teams
Contact sequences and sales engagement
Conversation and deal insights
Revenue forecasting', 'B2B-команди продажів, керівники відділів і RevOps.', 'B2B sales teams, sales leaders and RevOps.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
