SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'lavender.ai' OR LOWER(`name`) = LOWER('Lavender'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Lavender', NULL, 'https://www.lavender.ai', NULL, NULL, 'AI-коуч для холодних листів: у реальному часі оцінює текст листа, підказує, як підвищити шанс відповіді, і пише чернетки за допомогою агента Ora.', 'An AI coach for cold emails: it scores your email in real time, suggests how to improve the chance of a reply and writes drafts with the Ora agent.', 'Lavender допомагає продавцям писати холодні листи, на які відповідають. Сервіс навчено на мільярдах листів, тож він знає, що працює: прямо під час написання Email Coach оцінює лист, підказує, що скоротити чи змінити, перевіряє тон і читабельність, а AI-агент Ora готує персоналізовані чернетки на основі даних про отримувача. Lavender працює як розширення поверх поштових клієнтів, має сертифікацію SOC 2 і відповідає GDPR. Коуча можна встановити безкоштовно; ціни платних тарифів на головній сторінці не вказано.', 'Lavender helps salespeople write cold emails that get replies. It has been trained on billions of emails, so it knows what works: as you write, the Email Coach scores the email, suggests what to cut or change and checks tone and readability, while the Ora AI agent prepares personalised drafts based on data about the recipient. Lavender works as an extension on top of email clients, is SOC 2 certified and GDPR compliant. The Coach can be installed for free; paid plan prices are not shown on the home page.', 'Оцінка листа в реальному часі
Підказки щодо довжини, тону й читабельності
AI-агент Ora для персоналізованих чернеток
SOC 2 і GDPR', 'Real-time email scoring
Tips on length, tone and readability
Ora AI agent for personalised drafts
SOC 2 and GDPR', 'SDR, менеджери з продажів і засновники, які пишуть багато холодних листів.', 'SDRs, account executives and founders who write a lot of cold emails.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
